def transform(grid):
    row = grid[0]; W = len(row); s = row.index(2)
    g = [[0]*W for _ in range(W)]
    for r in range(W):
        for c in range(W):
            d = c - r
            if r <= min(s, W-1-s) and (c == s-r or c == s+r):
                g[r][c] = 2
            elif (d - s) % 4 == 0 and 0 <= s - d and (s - d) % 2 == 0 and r > (s-d)//2 and r >= 1:
                g[r][c] = 1
    return g
